import {animatePage,animateGrid,bindDepth} from './motion.js';
import {bindStackInteraction as bindStack} from './stack-interaction.js';
import {bindCardTilt} from './card-tilt.js';
import {bindRail} from './rail.js';
import {bindReview} from './review.js';
import {keyword,matchesKeyword,savedOrder,saveOrder,moodCards,moodPage,bindExperience,bindAmbient} from './experience.js';
import {audioReview,bindAudio} from './audio-review.js';
import {artistSidebar,bindDiscovery} from './discovery.js';
import {reviewByline,editorialCard,editorialPage,aboutPage,bindEditorial} from './editorial.js';
import {bindMoodStudio} from './mood-studio.js';
import {tvPage,tvDetail,bindTV,shows,tvSearchResults} from './tv.js';
import {adminPage,bindAdmin} from './admin.js';
const featuredIds=['anatole-muster-hopecore','cyst-00','nate-sib-reborn','dorian-electra','burial-untrue'];
const highlights=()=>{const editorial=albums.filter(a=>a.placement==='radar'&&a.score>=9),defaults=savedOrder(featuredIds).map(id=>albums.find(a=>a.id===id)).filter(Boolean);return [...editorial,...defaults].filter((a,i,list)=>list.findIndex(x=>x.id===a.id)===i).slice(0,5)};
const weekly=()=>albums.find(a=>a.placement==='frequency'&&a.score>=9)||albums[0];
const imageAttrs=(a,sizes='(max-width: 600px) 80vw, 320px')=>a.coverVariants?.length?`srcset="${a.coverVariants.map(v=>esc(v.src)+' '+v.width+'w').join(', ')}" sizes="${sizes}"`:'';
const railControls=()=>`<div class="rail-controls"><div class="rail-buttons"><button data-rail-prev aria-label="Discos anteriores">←</button><button data-rail-next aria-label="Próximos discos">→</button></div><span class="rail-position" aria-live="polite"></span><input class="rail-slider" type="range" min="0" max="100" value="0" step="0.1" aria-label="Posição na coleção horizontal"></div>`;
const app=document.querySelector('#app');
const reader=document.querySelector('#reader');
let albums=[];
let filterYear='all',filterGenre='all',query='',sort='recent',searchKind='all',filterSelection='all';
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const filteredAlbums=()=>albums.filter(a=>(filterSelection==='all'||featuredIds.includes(a.id))&&(filterYear==='all'||String(a.release).slice(0,4)===filterYear)&&(filterGenre==='all'||a.genre===filterGenre)&&matchesKeyword(a,query,searchKind));
const releaseYear=a=>a.release?new Date(a.release).getFullYear():'—';

function stackGallery(list){const first=list[0];return `<div class="stack-gallery"><div class="stack-scene" role="group" aria-label="Coleção de álbuns em camadas">${list.map((a,i)=>`<button class="stack-cover ${i===0?'is-selected':''}" style="--layer:${i}" aria-label="Abrir review de ${esc(a.title)}, ${esc(a.artist)}" aria-pressed="${i===0}" data-id="${a.id}" data-title="${esc(a.title)}" data-artist="${esc(a.artist)}" data-genre="${esc(a.genre)}" data-score="${Math.round(a.score)}" data-href="#album/${a.id}"><img src="${esc(a.cover)}" ${imageAttrs(a,'(max-width: 600px) 185px, 260px')} alt="" width="600" height="600" draggable="false"></button>`).join('')}</div><div class="stack-caption"><span class="eyebrow">TOP 5 DA SEMANA</span><div aria-live="polite" aria-atomic="true"><a class="stack-title-link" href="#album/${first.id}"><strong>${esc(first.title)}</strong></a><p class="stack-artist">${esc(first.artist)}</p><div class="stack-tags"><p class="stack-genre genre-tag">${esc(first.genre)}</p><span class="stack-rating">${Math.round(first.score)}</span></div></div><div class="stack-controls"><button data-stack-prev aria-label="Álbum anterior">←</button><span class="stack-position">01 / ${String(list.length).padStart(2,'0')}</span><button data-stack-next aria-label="Próximo álbum">→</button></div></div></div>`;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const duration=ms=>`${Math.floor((ms||0)/60000)}:${String(Math.floor((ms||0)/1000)%60).padStart(2,'0')}`;

function card(a){return `<article class="album-card specimen-card" style="--cover-color:${a.color}"><a class="cover-wrap" href="#album/${a.id}" aria-label="Review de ${esc(a.title)}"><img src="${esc(a.cover)}" ${imageAttrs(a)} alt="Capa de ${esc(a.title)}, ${esc(a.artist)}" loading="lazy" decoding="async" width="${a.coverWidth||600}" height="${a.coverHeight||600}"></a><div class="specimen-info"><div class="card-kicker"><p class="card-artist">${keyword(a.artist,"person")}</p><span class="card-type">${esc(a.type)}</span></div><p class="card-year">${keyword(releaseYear(a),"year")}</p><h3><a href="#album/${a.id}">${esc(a.title)}</a></h3><div class="card-bottom"><span class="card-genre">${keyword(a.genre,"genre")}</span><span class="score">${Math.round(a.score)}<small>/10</small></span></div><div class="card-footnote"><a href="#album/${a.id}">Ver mais ↗</a></div></div></article>`;}
function tools(){return `<div class="collection-tools"><div class="collection-scopes"><select id="year-filter" aria-label="Ano de lançamento"><option value="all">Anos · todos</option>${Array.from(new Set(albums.map(a=>String(a.release).slice(0,4)))).sort().reverse().map(y=>`<option value="${y}" ${filterYear===y?'selected':''}>${y}</option>`).join('')}</select><select id="selection-filter" aria-label="Seleção editorial"><option value="all" ${filterSelection==='all'?'selected':''}>Todas as reviews</option><option value="weekly" ${filterSelection==='weekly'?'selected':''}>Top 5 da semana</option></select></div><div class="tools-right"><input type="search" aria-label="Buscar álbum, artista, produtor, gênero ou ano" placeholder="Buscar no arquivo…" value="${esc(query)}"><select id="genre-filter" aria-label="Filtrar por gênero"><option value="all">Todos os gêneros</option>${Array.from(new Set(albums.map(a=>a.genre))).sort().map(g=>`<option value="${esc(g)}" ${filterGenre===g?'selected':''}>${esc(g)}</option>`).join('')}</select><select id="sort-filter" aria-label="Ordenação"><option value="recent" ${sort==='recent'?'selected':''}>Escutas recentes</option><option value="rating" ${sort==='rating'?'selected':''}>Maiores notas</option><option value="title" ${sort==='title'?'selected':''}>Título A–Z</option></select></div></div>`;}
function results(home=false){let list=filteredAlbums();if(sort==='rating')list.sort((a,b)=>b.score-a.score);if(sort==='title')list.sort((a,b)=>a.title.localeCompare(b.title));if(home)list=list.slice(0,10);return list.length?list.map(card).join(''):'<p class="empty">Nenhum disco por aqui. Experimente outro gênero ou uma busca diferente. <button class="clear-filters">Limpar filtros</button></p>';}
const article=()=>editorialCard(albums.find(a=>a.id==='burial-untrue')||albums[0]);
function home(){const a=weekly();return `<section class="intro"><div><h1>Opinião com escuta atenta.</h1></div><p>Um lugar para os discos que ficam,<br>as palavras e as descobertas.</p></section><section class="hero" aria-label="Recomendação da semana"><div class="hero-copy"><span class="pill">↗ Na frequência da semana</span><h2><a href="#album/${a.id}">${esc(a.title)}</a></h2><p class="artist">${esc(a.artist)} <span class="small">/ ${releaseYear(a)}</span></p><p class="quote">${esc(a.review[0])} Uma descoberta para ouvir de perto.</p><div class="hero-actions"><a class="solid" href="#album/${a.id}">Abrir o disco <span>↗</span></a><a class="text-link" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.listenLabel)} ↗</a></div></div><div class="hero-art"><div class="vinyl" aria-hidden="true"></div><a href="#album/${a.id}" aria-label="Abrir review de ${esc(a.title)}"><img class="hero-cover" src="${a.cover}" ${imageAttrs(a,'(max-width: 600px) 80vw, 520px')} alt="Capa de ${esc(a.title)}" width="600" height="600"></a><div class="rating-sticker"><strong>${Math.round(a.score)}</strong></div></div></section><section class="section radar-section"><div class="section-head"><div><h2>No meu radar</h2></div></div><div id="radar-highlights">${stackGallery(highlights())}</div></section><section class="section collection-section"><div class="section-head"><div><h2>Reviews</h2></div><a href="#arquivo">Ver todas ↗</a></div>${tools()}<div class="album-grid album-rail" id="album-results" tabindex="0" role="region" aria-label="Coleção de discos, role horizontalmente">${results(true)}</div>${railControls()}</section><section class="bottom-grid"><div><div class="section-head"><h2>À margem do som</h2><a href="#textos">Todos os textos ↗</a></div>${article()}</div><div><div class="section-head"><h2>Universo visual</h2><a href="#moods">Ver moods ↗</a></div>${moodCards()}</div></section>`;}
function archive(){return `<section class="page-heading"><h1>Todas as reviews.</h1><p>Discos e opiniões, organizados por ano de lançamento.<br>Explore por artista, gênero ou seleção.</p></section><section class="archive">${tools()}<div class="album-grid album-rail" id="album-results" tabindex="0" role="region" aria-label="Arquivo de discos, role horizontalmente">${results()}</div>${railControls()}</section>`;}
const creditList=items=>items?.length?items.map(c=>`<span class="credit-person">${keyword(c.name,"person")} <small>· ${esc(c.role)}</small>${c.source?.url?` <a class="credit-source" href="${esc(c.source.url)}" target="_blank" rel="noopener noreferrer" aria-label="Fonte do crédito de ${esc(c.name)}">↗</a>`:''}</span>`).join(''):'<span class="metadata-pending">Não informado nas fontes consultadas</span>';
function technical(a){const all=[...(a.credits||[]),...a.tracks.flatMap(t=>t.credits||[])].filter((c,i,list)=>list.findIndex(x=>x.name===c.name&&x.role===c.role)===i).sort((a,b)=>Number(/produ/i.test(b.role))-Number(/produ/i.test(a.role)));return `<section class="technical-credits"><h2>Produção e créditos</h2><div class="credits-list">${creditList(all.slice(0,4))}</div>${all.length>4?`<details class="credits-more"><summary>Ver todos os créditos</summary><div class="credits-list">${creditList(all.slice(4))}</div></details>`:''}${all.length?'<p class="small">Créditos reunidos do álbum e de suas faixas; os detalhes aparecem abaixo.</p>':''}</section>`;}
function trackFacts(t){return `<div class="track-facts"><div><span class="eyebrow">BPM</span><p>${t.bpm>0?`${Number(t.bpm).toLocaleString('pt-BR',{maximumFractionDigits:2})}${t.bpmSource?.url?` <a class="credit-source" href="${esc(t.bpmSource.url)}" target="_blank" rel="noopener noreferrer" aria-label="Fonte do BPM">↗</a>`:''}`:'<span class="metadata-pending">Não informado</span>'}</p></div><div><span class="eyebrow">CRÉDITOS</span><div class="credits-list">${creditList(t.credits)}</div></div></div>`;}

function reviewContent(a){const original=a.reviewOriginal;return `<section class="detail-copy ${original?'original-review':''}" id="transcricao"><span class="eyebrow">${original?'REVIEW DE LUCAS':'ANOTAÇÕES DE ESCUTA'}</span><h2>${esc(a.review[0])}</h2>${(original?.paragraphs||a.review.slice(1)).map(p=>'<p>'+esc(p)+'</p>').join('')}${original?'':'<span class="demo-note">TEXTO ILUSTRATIVO · NÃO É UMA REVIEW DO LUCAS</span>'}</section>`;}
function detail(id){const a=albums.find(x=>x.id===id);if(!a)return '<div class="empty">Álbum não encontrado. <a href="#arquivo">Voltar ao arquivo.</a></div>';const n=a.review;return `<a class="detail-back" href="#arquivo">← Voltar ao arquivo</a><article class="album-detail"><div class="review-sidebar"><div class="detail-art"><div class="artwork-deck ${a.backCover?'has-back':''}" data-title="${esc(a.title)}" data-front="${esc(a.coverOriginal||a.cover)}" data-back="${esc(a.backCoverOriginal||a.backCover||'')}"><div class="artwork-stage">${a.backCover?`<img class="artwork-back" src="${esc(a.backCover)}" alt="Contracapa de ${esc(a.title)}">`:''}<button type="button" class="artwork-front" aria-label="Ampliar capa de ${esc(a.title)}"><img src="${esc(a.cover)}" ${imageAttrs(a,'(max-width: 600px) 80vw, 520px')} alt="Capa de ${esc(a.title)}" width="${a.coverWidth||600}" height="${a.coverHeight||600}"><span class="artwork-zoom" aria-hidden="true">Ampliar ↗</span></button></div><div class="artwork-meta"><span>${releaseYear(a)} · ${esc(a.type)}</span></div></div></div>${artistSidebar(a,albums)}</div><div class="review-main">${reviewByline(a)}<div class="detail-top"><div><span class="eyebrow">${keyword(a.artist,"person")}</span><h1>${esc(a.title)}</h1></div><div class="review-rating"><div class="detail-score">${Math.round(a.score)}</div>${Math.round(a.score)===10?'<span class="perfect-seal" aria-label="Nota máxima">✳<small>NOTA<br>MÁXIMA</small></span>':''}</div></div><p class="metadata">${keyword(releaseYear(a),"year")} · ${esc(a.type)} · ${keyword(a.genre,"genre")}${a.tracks.length?' · '+a.tracks.length+' faixas · '+Math.round(a.tracks.reduce((s,t)=>s+t.duration,0)/60000)+' min':''}<br>Ouvido em ${a.listened} · ${a.reviewOriginal?'Nota de Lucas':'Nota de demonstração'}</p><a class="solid" target="_blank" rel="noopener noreferrer" href="${esc(a.url)}">${esc(a.listenLabel)} ↗</a>${a.catalogDescription?`<section class="catalog-description"><span class="eyebrow">SOBRE O LANÇAMENTO</span><p>${esc(a.catalogDescription)}</p><span class="small">Resumo dos dados de ${esc(a.sources?.map(s=>s.name).join(', ')||a.source)}.</span></section>`:''}${audioReview(a)}${reviewContent(a)}${technical(a)}<details class="track-section track-disclosure"><summary class="track-disclosure-heading"><h2>Faixa a faixa <sup>${a.tracks.length}</sup></h2><span class="track-expand-label">Ver faixas +</span></summary><div class="track-disclosure-body">${a.tracks.length?a.tracks.map(t=>`<details class="track"><summary><span class="track-num">${String(t.number).padStart(2,'0')}</span><span class="track-name">${esc(t.name)}</span>${t.bpm>0?`<span class="track-bpm">${Number(t.bpm).toLocaleString('pt-BR',{maximumFractionDigits:2})} BPM</span>`:''}<span class="duration">${duration(t.duration)}</span><span aria-hidden="true">+</span></summary><div class="track-body"><a href="${esc(t.url)}" target="_blank" rel="noopener noreferrer">Ouvir a faixa ↗</a><a href="https://genius.com/search?q=${encodeURIComponent(a.artist+' '+t.name)}" target="_blank" rel="noopener noreferrer">Buscar letra no Genius ↗</a>${trackFacts(t)}</div></details>`).join(''):'<p class="metadata">Faixas ainda não confirmadas no catálogo. Consulte o lançamento pelo link acima.</p>'}</div></details><div class="facts"><div><span>LANÇAMENTO DESTA EDIÇÃO</span>${a.releaseVerified||a.source==='Apple / iTunes'?new Date(a.release).toLocaleDateString('pt-BR',{timeZone:'UTC'}):'Ano da referência: '+(a.release||'a confirmar')}</div><div><span>FONTES DO CATÁLOGO</span>${a.sources?.length?a.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`).join(' · '):esc(a.source)}</div><div><span>SELO</span>${esc(a.label||'A confirmar')}</div><div><span>GÊNERO · CURADORIA PROVISÓRIA</span>${esc(a.genre)}</div><div><span>CAPA</span>${esc(a.coverSource||a.source)} · ${a.coverWidth||'—'} × ${a.coverHeight||'—'}</div></div>${comments(a)}</div></article>`;}
function comments(a){return `<section class="comments-section" data-album="${a.id}"><div class="section-head"><h2>Comentários</h2></div><form class="comment-form"><label>Seu nick<input name="nick" maxlength="32" required autocomplete="nickname" placeholder="Como quer aparecer"></label><label class="comment-grade">Sua nota<select name="score" required aria-label="Sua nota de 0 a 10"><option value="">Selecione</option>${Array.from({length:11},(_,i)=>`<option value="${i}">${i}</option>`).join('')}</select></label><label class="comment-message">O que achou do disco?<textarea name="body" maxlength="2000" rows="3" required placeholder="Compartilhe sua escuta…"></textarea></label><button class="solid" type="submit">Publicar comentário ↗</button><p class="comment-status" role="status" aria-live="polite"></p></form><div class="comment-list"></div><button class="comments-more" type="button" hidden>Ver mais comentários</button></section>`;}

function texts(){return editorialPage(albums[0]);}
function moods(){return `<section class="page-heading"><span class="eyebrow">MOOD BOARD / 01</span><h1>Cor, ruído & frequência.</h1><p>Um primeiro recorte das referências visuais do projeto.<br>Imagens reunidas por Lucas para estudo de direção visual.</p></section><div class="mood-board"><figure><img src="assets/mood-texture.jfif" alt="Degradê vibrante com textura de retícula"><figcaption>01 / Cor e retícula</figcaption></figure><figure><img src="assets/mood-vinyl.jfif" alt="Referência gráfica de embalagem de vinil amarelo"><figcaption>02 / O disco como objeto</figcaption></figure><figure><img src="assets/mood-layers.jpg" alt="Referência de interface com imagens sobrepostas"><figcaption>03 / Imagens em camadas</figcaption></figure></div>`;}
function about(){return aboutPage(albums);}
function openArticle(){document.querySelector('#reader-content').innerHTML=`<span class="eyebrow">CADERNO DE ESCUTA / TEXTO DE EXEMPLO</span><h1>O que muda quando você ouve de novo?</h1><p class="small">Prévia editorial · 2 min de leitura</p><img src="${albums[0].cover}" alt="Capa de ${esc(albums[0].title)}"><p>Às vezes, a gente volta a um disco pela mesma razão que volta a uma rua. Não há exatamente uma novidade esperando. Há uma luz conhecida, um caminho que o corpo aprendeu, alguma coisa que só aparece quando não estamos procurando.</p><p>Na primeira escuta, procuro uma música. Nas seguintes, começo a perceber os intervalos: a entrada de um instrumento, uma palavra que demora, o silêncio antes de tudo mudar.</p><p>Guardar um álbum num arquivo é também guardar esse momento. O disco continua o mesmo; quem aperta o play já é um pouco diferente.</p><p class="demo-note">Texto criado para demonstrar a página de leitura. Não publicado como texto do Lucas.</p>`;reader.showModal();reader.classList.add('notebook-reader');}
function bind(){const homePage=!location.hash||location.hash==='#inicio';const refresh=()=>{const grid=document.querySelector('#album-results');grid.innerHTML=results(homePage);const count=document.querySelector('.result-count');if(count)count.textContent=filteredAlbums().length+' de '+albums.length+' lançamentos';bindDepth(grid);animateGrid(grid);bindRail(app);const tvResults=document.querySelector("#tv-search-results");if(tvResults){tvResults.innerHTML=tvSearchResults(query,searchKind);bindTV(app);}bindDiscovery(app,albums);};document.querySelectorAll('[data-year]').forEach(b=>b.addEventListener('click',()=>{filterYear=b.dataset.year;document.querySelectorAll('[data-year]').forEach(x=>{const on=x.dataset.year===filterYear;x.classList.toggle('selected',on);x.setAttribute('aria-pressed',String(on));});refresh();}));document.querySelector('.collection-tools input[type=search]')?.addEventListener('input',e=>{query=e.target.value;if(location.hash.startsWith('#busca')){history.replaceState(null,'','#busca?'+new URLSearchParams({q:query,tipo:searchKind}));const label=document.querySelector('.search-query');if(label)label.textContent=query||'Todas as reviews';}refresh();});document.querySelector('#year-filter')?.addEventListener('change',e=>{filterYear=e.target.value;refresh();});document.querySelector('#selection-filter')?.addEventListener('change',e=>{filterSelection=e.target.value;refresh();});document.querySelector('#sort-filter')?.addEventListener('change',e=>{sort=e.target.value;refresh();});document.querySelector('#genre-filter')?.addEventListener('change',e=>{filterGenre=e.target.value;refresh();});app.onclick=e=>{if(e.target.closest('.clear-filters')){filterGenre='all';filterYear='all';filterSelection='all';query='';if(location.hash.startsWith('#busca'))history.replaceState(null,'','#busca');render();}};const grid=document.querySelector('#album-results');if(grid&&!homePage){const count=document.createElement('p');count.className='result-count';count.setAttribute('aria-live','polite');count.textContent=filteredAlbums().length+' de '+albums.length+' lançamentos';grid.before(count);}bindStack(app,ids=>saveOrder(ids));bindDepth(app);animatePage(app);bindRail(app);bindReview(app);bindExperience(app);bindTV(app);bindMoodStudio(app,albums);bindEditorial(app);bindDiscovery(app,albums);bindCardTilt(app);bindAudio(app,albums.find(a=>a.id===location.hash.split("/")[1]));}
function render(){const route=location.hash.slice(1)||'inicio';const special=route.startsWith('album/')&&Math.round(albums.find(a=>a.id===route.split('/')[1])?.score)===10;document.body.classList.toggle('review-special',special);document.querySelector('meta[name="theme-color"]')?.setAttribute('content',special?'#101118':'#f7f6f3');if(route.startsWith('busca')){const params=new URLSearchParams(route.split('?')[1]||'');query=params.get('q')||'';searchKind=['person','genre','year'].includes(params.get('tipo'))?params.get('tipo'):'all';filterYear='all';filterGenre='all';filterSelection='all';}else searchKind='all';if(reader.open)reader.close();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route||(route.startsWith('busca')&&a.hash==='#busca')||(route.startsWith('moods/')&&a.hash==='#moods')||(route.startsWith('tv/')&&a.hash==='#tv')||(route.startsWith('album/')&&a.hash==='#arquivo')));if(route.startsWith('texto/')){app.innerHTML=texts();openArticle();}else app.innerHTML=route==='inicio'?home():route==='arquivo'?archive():route.startsWith('busca')?searchPage():route==='textos'?texts():route.startsWith('moods')?moodPage(albums,route.split('/')[1]):route==='tv'?tvPage():route.startsWith('tv/')?tvDetail(route.split('/')[1]):route==='sobre'?about():route.startsWith('album/')?detail(route.split('/')[1]):'<p class="empty">Página não encontrada. <a href="#inicio">Voltar ao início.</a></p>';bind();window.scrollTo(0,0);document.title=route.startsWith('album/')?`${albums.find(a=>a.id===route.split('/')[1])?.title??'Álbum'} — meeting.points`:route.startsWith('tv/')?`${shows.find(s=>s.id===route.split('/')[1])?.title??'TV'} — meeting.points TV`:'meeting.points — arquivo de escuta';}
function searchPage(){return `<section class="page-heading"><span class="eyebrow">BUSCA NO ARQUIVO</span><h1 class="search-query">${esc(query)||'Todas as reviews'}</h1><p>Discos, shows, artistas e as conexões entre eles.</p></section><section class="archive">${tools()}<div class="album-grid album-rail" id="album-results" tabindex="0" role="region" aria-label="Resultados da busca">${results()}</div>${railControls()}</section><div id="tv-search-results">${tvSearchResults(query,searchKind)}</div>`;}
bindAmbient();
reader.querySelector('.close').addEventListener('click',()=>reader.close());reader.addEventListener('click',e=>{if(e.target===reader){const r=reader.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)reader.close();}});reader.addEventListener('close',()=>{if(location.hash.startsWith('#texto/'))location.hash='textos';});
window.addEventListener('hashchange',()=>{if(!albums.length)return;if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const transition=document.startViewTransition(render);transition.ready.catch(()=>{});}else render();});
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 try{Promise.resolve(document.modelContext.registerTool({name:'filter_album_archive',title:'Filtrar arquivo musical',description:'Abre o arquivo e filtra os álbuns por artista, título e ano de lançamento. Não modifica o acervo.',inputSchema:{type:'object',properties:{query:{type:'string'},year:{type:'string'},genre:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||(input.query!==undefined&&typeof input.query!=='string')||(input.year!==undefined&&!['all',...new Set(albums.map(a=>String(a.release).slice(0,4)))].includes(input.year))||(input.genre!==undefined&&input.genre!=='all'&&!albums.some(a=>a.genre===input.genre))||Object.keys(input).some(k=>!['query','year','genre'].includes(k)))throw Error('Filtro inválido');if(!albums.length)throw Error('Catálogo ainda não carregado');query=input.query??'';filterYear=input.year??'all';filterGenre=input.genre??'all';history.replaceState(null,'','#arquivo');render();return {albums:filteredAlbums().map(a=>({id:a.id,title:a.title,artist:a.artist,score:a.score}))};}},{signal:lifecycle.signal})).catch(console.warn);}catch(e){console.warn(e);}
}
try{const r=await fetch('catalog.json');if(!r.ok)throw Error('Catálogo indisponível');albums=await r.json();if(!albums.length)throw Error('Catálogo vazio');render();}catch(e){app.innerHTML='<div class="error"><h1>Não conseguimos abrir a coleção.</h1><p>Recarregue a página para tentar novamente.</p><button id="retry">Tentar novamente</button></div>';document.querySelector('#retry').onclick=()=>location.reload();console.error(e);}
